#include <iostream>

using namespace std;

int main() {
    // Takahashi と等しい個数のカウンタ
    int ans = 0;

    int N;
    cin >> N;

    for (int i = 0; i < N; i++) {
        string S;
        cin >> S;
        // S が Takahashi と等しかったら、カウンタの値を増やす
        if (S == "Takahashi") {
            ans++;
        }
    }

    // カウンタの値を出力
    cout << ans << endl;

    return 0;
}
